function rTier2(el){ const a=cur(); if(!a){ needSite(el); return; } const r=ATRF.run(engineInputs(a));
  el.innerHTML=`<div class="card"><h3>Tier 2 - findings and actions (${esc(r.next||"Tier 2 status follows the decision")})</h3><p class="muted">Only when Results says Tier 2 is Required or Recommended: log risks, barriers, assumptions, opportunities and monitoring programmes. Open critical items deduct from the TRI (at most -30% of BRS); realised results add (at most +10%). Every opportunity is a hypothesis with a named approver.</p>
  <h4>Findings</h4><div id="fg"></div><h4>Actions that lift ratings (projected TRI gain in points; realised results add TOA when Implemented or Verified)</h4><div id="ag"></div>
  <h4>Requirements versus assumptions (engine sheet Step 3) - what is truly required versus what has always been done</h4><div id="rg"></div><p class="muted">Binding obligations (Regulatory requirement, Permit commitment) are never optimised here; they need a cited source.</p></div>`;
  grid($("#fg"),a.findings,[{k:"id",label:"ID",rows:1},{k:"type",label:"Type",type:"select",options:L.findingType},{k:"text",label:"Finding"},{k:"criteria",label:"Criteria affected",rows:1},{k:"criticality",label:"Criticality",type:"select",options:["Critical","Major","Minor"]},{k:"toa",label:"TOA class",type:"select",options:L.toaClass},{k:"owner",label:"Owner",rows:1},{k:"gate",label:"Approval gate",type:"select",options:["Site lead","Asset transition team","Corporate closure","Client leadership","Regulator","Rights-holder"]},{k:"status",label:"Status",type:"select",options:L.findingStatus}],()=>render(),{newRow:n=>({id:`FND-${(siteOf(DB.current)||{}).code||"XXX"}-${String(n+1).padStart(2,"0")}`,status:"Open",toa:"None"})});
  grid($("#ag"),a.actions,[{k:"id",label:"ID",rows:1},{k:"action",label:"Action"},{k:"type",label:"Type",type:"select",options:L.actionType},{k:"criteria",label:"Criteria lifted",rows:1},{k:"gain",label:"Projected TRI gain (pts)",type:"num",step:0.1},{k:"result",label:"Result realised",type:"select",options:L.toaPos},{k:"owner",label:"Owner",rows:1},{k:"due",label:"Due",rows:1},{k:"status",label:"Status",type:"select",options:L.actionStatus}],()=>render(),{newRow:n=>({id:`ACT-${(siteOf(DB.current)||{}).code||"XXX"}-${String(n+1).padStart(2,"0")}`,status:"Proposed",result:"None"})});
  grid($("#rg"),a.rva,[{k:"id",label:"ID",rows:1},{k:"commitment",label:"Commitment as the plan states it"},{k:"outcome",label:"Required OUTCOME"},{k:"method",label:"Current METHOD"},{k:"source",label:"Source cited (instrument, clause)",rows:1},{k:"cls",label:"Obligation class",type:"select",options:L.obligationClass},{k:"status",label:"Status",type:"select",options:["Open","Validated","Retired","Superseded"]}],()=>save(),{newRow:n=>({id:`RVA-${(siteOf(DB.current)||{}).code||"XXX"}-${String(n+1).padStart(2,"0")}`,status:"Open"})}); }
